from pathlib import Path
import base64,gzip
DATA={"1401":"","1402":"","1403":"","1404":"","summary":"","report":""}
root=Path(__file__).resolve().parents[1]
targets={"1401":"data/capacity/normalized/1401/capacities-nutrition-radiology.csv","1402":"data/capacity/normalized/1402/capacities-nutrition-radiology.csv","1403":"data/capacity/normalized/1403/capacities-nutrition-radiology.csv","1404":"data/capacity/normalized/1404/capacities-nutrition-radiology.csv","summary":"data/capacity/NUTRITION_RADIOLOGY_SUMMARY.json","report":"data/capacity/NUTRITION_RADIOLOGY_REPORT.md"}
for k,rel in targets.items():
    p=root/rel
    p.parent.mkdir(parents=True,exist_ok=True)
    p.write_bytes(gzip.decompress(base64.b64decode(DATA[k])))
    print("wrote",rel)
